fn reverse(a: &Vec<char>) -> Vec<char> {
    let len = a.len();
    // Pre-allocate a vector with the same capacity as the input
    let mut result = Vec::with_capacity(len);
    // Iterate from the end of the input to the beginning
    let mut i = 0;
    while i < len {
        // Push the element at position (len - 1 - i)
        result.push(a[len - 1 - i]);
        i += 1;
    }
    result
}

